    WHERE doc_type = 'cber_lot_release' AND agency = 'fda' AND version = 'fda-cber-lot-release-v1.0';
    UPDATE c2c_rule_packs SET
      source_basis   = 'reasoned_construction',
      confidence     = 'low',
      governing_rule = 'FD&C Act section 564 (authorization for medical products for use in emergencies; 21 U.S.C. 360bbb-3) (recall: not re-read for this record); FD&C Act section 564(b) (HHS Secretary declaration that circumstances exist justifying emergency use) (recall: not re-read for this record); FD&C Act section 564(c) (criteria: serious or life-threatening disease or condition, may be effective, known and potential benefits outweigh known and potential risks, no adequate approved and available alternative) (recall: not re-read for this record); FD&C Act section 564(e) (conditions of authorization, including information to health care providers and recipients and adverse event monitoring and reporting) (recall: not re-read for this record); FDA guidance: Emergency Use Authorization of Medical Products and Related Authorities (January 2017) (recall: title and date not re-read on fda.gov) (recall — not checked against the regulator''s text)',
      uncertainties  = 'An advisory platform record that cites the rule; its headings are recalled, not transcribed. Every basis is recall: eCFR and fda.gov were unreachable from the build environment on 2026-10-29, so no section was re-read for it. Minted 2026-10-29 from lifecycle-record LIFECYCLE_DOCUMENT_TYPES:us_eua_therapeutic. The regulator''s text was not re-read for this pack (regulator hosts are unreachable from the build environment). Not reviewed by a regulatory professional.'
    WHERE doc_type = 'eua_request' AND agency = 'fda' AND version = 'fda-eua-request-v1.0';
  END IF;

  -- 4 ── Supersede exactly the version each pack replaces, and say so on it.
  -- (none: every pack here is its class's first)
  IF EXISTS (SELECT 1 FROM information_schema.columns
              WHERE table_name = 'c2c_rule_packs' AND column_name = 'source_basis') THEN
    NULL;
  END IF;

  -- 5 ── Assertions (CLAUDE.md Rule 1, seed corollary). A tree the CASE does not
  --      name is refused, never read as a match.
  FOR e IN SELECT * FROM jsonb_array_elements(expected) LOOP
    tree := CASE (e->>'doc_type') || ':' || (e->>'agency') || ':' || (e->>'version')
    WHEN 'type_d_meeting:fda:fda-type-d-meeting-v1.0' THEN $pack$[{"key":"MTG-REQ-CL","parent_key":null,"label":"Meeting Request Letter and Cover Letter","mandatory":true,"path_order":1},{"key":"MTG-D-SCOPE","parent_key":null,"label":"Focused Topics and Disciplines Scope Statement","mandatory":true,"path_order":2},{"key":"MTG-AGENDA","parent_key":null,"label":"Proposed Agenda","mandatory":true,"path_order":3},{"key":"MTG-ATTEND","parent_key":null,"label":"Sponsor Attendee List","mandatory":true,"path_order":4},{"key":"MTG-BKGD","parent_key":null,"label":"Product Background and Development History","mandatory":true,"path_order":5},{"key":"MTG-QUES","parent_key":null,"label":"Numbered Questions for FDA with Sponsor Positions","mandatory":true,"path_order":6}]$pack$::jsonb
    WHEN 'interact_meeting:fda:fda-interact-meeting-v1.0' THEN $pack$[{"key":"MTG-REQ-CL","parent_key":null,"label":"Meeting Request Letter and Cover Letter","mandatory":true,"path_order":1},{"key":"MTG-INTERACT-NOVEL","parent_key":null,"label":"Novel Issue and INTERACT Eligibility Statement","mandatory":true,"path_order":2},{"key":"MTG-AGENDA","parent_key":null,"label":"Proposed Agenda","mandatory":true,"path_order":3},{"key":"MTG-ATTEND","parent_key":null,"label":"Sponsor Attendee List","mandatory":true,"path_order":4},{"key":"MTG-BKGD","parent_key":null,"label":"Product Background and Development History","mandatory":true,"path_order":5},{"key":"MTG-QUES","parent_key":null,"label":"Numbered Questions for FDA with Sponsor Positions","mandatory":true,"path_order":6}]$pack$::jsonb
    WHEN 'expanded_access_individual:fda:fda-expanded-access-individual-v1.0' THEN $pack$[{"key":"EAI-ROLE","parent_key":null,"label":"Submitter Role and Access Path","mandatory":true,"path_order":1},{"key":"EAI-3926","parent_key":null,"label":"Form FDA 3926 (Individual Patient Expanded Access IND), Physician Submission","mandatory":false,"path_order":2},{"key":"EAI-1571","parent_key":null,"label":"Form FDA 1571 (Sponsor Protocol Amendment or Non-3926 IND)","mandatory":false,"path_order":3},{"key":"EAI-LOA","parent_key":null,"label":"Letter of Authorization from the Manufacturer or IND Holder","mandatory":false,"path_order":4},{"key":"EAI-PATIENT","parent_key":null,"label":"Patient History and Current Condition","mandatory":true,"path_order":5},{"key":"EAI-RISK","parent_key":null,"label":"Physician Risk Determination and Unavailability Under Another IND","mandatory":true,"path_order":6},{"key":"EAI-RATIONALE","parent_key":null,"label":"Rationale for the Intended Use and Available Alternatives","mandatory":true,"path_order":7},{"key":"EAI-PLAN","parent_key":null,"label":"Treatment Plan and Monitoring","mandatory":true,"path_order":8},{"key":"EAI-CMC-PT","parent_key":null,"label":"Manufacturing, CMC and Pharmacology/Toxicology Information (or Cross-Reference)","mandatory":true,"path_order":9},{"key":"EAI-IRB-CONSENT","parent_key":null,"label":"IRB Review and Informed Consent Records","mandatory":true,"path_order":10},{"key":"EAI-EMERG-AUTH","parent_key":null,"label":"Emergency Authorization Record (Emergency Path Only)","mandatory":false,"path_order":11},{"key":"EAI-EMERG-IRB","parent_key":null,"label":"Emergency-Use IRB Report and Consent Record (Emergency Path Only)","mandatory":false,"path_order":12},{"key":"EAI-SUMMARY","parent_key":null,"label":"Written Summary of Results at Conclusion of Treatment","mandatory":false,"path_order":13}]$pack$::jsonb
    WHEN 'expanded_access_intermediate:fda:fda-expanded-access-intermediate-v1.0' THEN $pack$[{"key":"EAM-COVER","parent_key":null,"label":"Cover Letter","mandatory":true,"path_order":1},{"key":"EAM-1571","parent_key":null,"label":"Form FDA 1571 (IND Cover Sheet)","mandatory":true,"path_order":2},{"key":"EAM-1572","parent_key":null,"label":"Form FDA 1572 (Statement of Investigator) for Each Treating Physician","mandatory":true,"path_order":3},{"key":"EAM-NEED","parent_key":null,"label":"Need for Intermediate-Size Expanded Access and Development Status","mandatory":true,"path_order":4},{"key":"EAM-EVIDENCE","parent_key":null,"label":"Evidence of Safety and Effectiveness","mandatory":true,"path_order":5},{"key":"EAM-SELECTION","parent_key":null,"label":"Patient Selection Criteria","mandatory":true,"path_order":6},{"key":"EAM-RATIONALE","parent_key":null,"label":"Rationale for the Intended Use and Available Alternatives","mandatory":true,"path_order":7},{"key":"EAM-PLAN","parent_key":null,"label":"Treatment Plan and Monitoring","mandatory":true,"path_order":8},{"key":"EAM-CMC-PT","parent_key":null,"label":"Manufacturing, CMC and Pharmacology/Toxicology Information (or Cross-Reference)","mandatory":true,"path_order":9},{"key":"EAM-IRB-CONSENT","parent_key":null,"label":"IRB Review and Informed Consent Records","mandatory":true,"path_order":10},{"key":"EAM-CHARGING","parent_key":null,"label":"Request to Charge (Cost Recovery), if Sought","mandatory":false,"path_order":11}]$pack$::jsonb
    WHEN 'expanded_access_treatment:fda:fda-expanded-access-treatment-v1.0' THEN $pack$[{"key":"EAT-COVER","parent_key":null,"label":"Cover Letter","mandatory":true,"path_order":1},{"key":"EAT-1571","parent_key":null,"label":"Form FDA 1571 (IND Cover Sheet)","mandatory":true,"path_order":2},{"key":"EAT-1572","parent_key":null,"label":"Form FDA 1572 (Statement of Investigator) for Each Treating Physician","mandatory":true,"path_order":3},{"key":"EAT-STATUS","parent_key":null,"label":"Trial Status and Marketing Diligence","mandatory":true,"path_order":4},{"key":"EAT-EVIDENCE","parent_key":null,"label":"Evidence Standard (Serious vs Immediately Life-Threatening)","mandatory":true,"path_order":5},{"key":"EAT-SELECTION","parent_key":null,"label":"Patient Selection Criteria","mandatory":true,"path_order":6},{"key":"EAT-RATIONALE","parent_key":null,"label":"Rationale for the Intended Use and Available Alternatives","mandatory":true,"path_order":7},{"key":"EAT-PLAN","parent_key":null,"label":"Treatment Plan and Monitoring","mandatory":true,"path_order":8},{"key":"EAT-OVERSIGHT","parent_key":null,"label":"Sponsor Monitoring and Physician Compliance","mandatory":true,"path_order":9},{"key":"EAT-CMC-PT","parent_key":null,"label":"Manufacturing, CMC and Pharmacology/Toxicology Information (or Cross-Reference)","mandatory":true,"path_order":10},{"key":"EAT-IRB-CONSENT","parent_key":null,"label":"IRB Review and Informed Consent Records","mandatory":true,"path_order":11},{"key":"EAT-CHARGING","parent_key":null,"label":"Request to Charge (Cost Recovery), if Sought","mandatory":false,"path_order":12}]$pack$::jsonb
    WHEN 'bla_pas:fda:fda-bla-pas-v1.0' THEN $pack$[{"key":"bla_pas.cover","parent_key":null,"label":"Cover Letter","mandatory":true,"path_order":1},{"key":"bla_pas.356h","parent_key":null,"label":"Form FDA 356h","mandatory":true,"path_order":2},{"key":"bla_pas.description","parent_key":null,"label":"Detailed Description of the Change, Products and Sites Involved","mandatory":true,"path_order":3},{"key":"bla_pas.data","parent_key":null,"label":"Data From the Studies Evaluating the Change","mandatory":true,"path_order":4},{"key":"bla_pas.validation","parent_key":null,"label":"Validation Protocols, Data and SOP References","mandatory":true,"path_order":5},{"key":"bla_pas.labeling","parent_key":null,"label":"Labeling Changes","mandatory":false,"path_order":6},{"key":"CTD","parent_key":null,"label":"Updated CTD Sections","mandatory":false,"path_order":7},{"key":"2.3","parent_key":"CTD","label":"Quality Overall Summary (QOS)","mandatory":false,"path_order":8},{"key":"3.2.S","parent_key":"CTD","label":"Drug Substance","mandatory":false,"path_order":9},{"key":"3.2.P","parent_key":"CTD","label":"Drug Product","mandatory":false,"path_order":10},{"key":"3.2.A","parent_key":"CTD","label":"Appendices (Facilities and Equipment, Adventitious Agents Safety Evaluation, Excipients)","mandatory":false,"path_order":11},{"key":"3.2.R","parent_key":"CTD","label":"Regional Information","mandatory":false,"path_order":12}]$pack$::jsonb
    WHEN 'bla_cbe30:fda:fda-bla-cbe30-v1.0' THEN $pack$[{"key":"bla_cbe30.cover","parent_key":null,"label":"Cover Letter","mandatory":true,"path_order":1},{"key":"bla_cbe30.356h","parent_key":null,"label":"Form FDA 356h","mandatory":true,"path_order":2},{"key":"bla_cbe30.description","parent_key":null,"label":"Detailed Description of the Change, Products and Sites Involved","mandatory":true,"path_order":3},{"key":"bla_cbe30.data","parent_key":null,"label":"Data From the Studies Evaluating the Change","mandatory":true,"path_order":4},{"key":"bla_cbe30.validation","parent_key":null,"label":"Validation Protocols, Data and SOP References","mandatory":true,"path_order":5},{"key":"bla_cbe30.labeling","parent_key":null,"label":"Labeling Changes","mandatory":false,"path_order":6},{"key":"CTD","parent_key":null,"label":"Updated CTD Sections","mandatory":false,"path_order":7},{"key":"2.3","parent_key":"CTD","label":"Quality Overall Summary (QOS)","mandatory":false,"path_order":8},{"key":"3.2.S","parent_key":"CTD","label":"Drug Substance","mandatory":false,"path_order":9},{"key":"3.2.P","parent_key":"CTD","label":"Drug Product","mandatory":false,"path_order":10},{"key":"3.2.A","parent_key":"CTD","label":"Appendices (Facilities and Equipment, Adventitious Agents Safety Evaluation, Excipients)","mandatory":false,"path_order":11},{"key":"3.2.R","parent_key":"CTD","label":"Regional Information","mandatory":false,"path_order":12}]$pack$::jsonb
    WHEN 'bla_cbe0:fda:fda-bla-cbe0-v1.0' THEN $pack$[{"key":"bla_cbe0.cover","parent_key":null,"label":"Cover Letter","mandatory":true,"path_order":1},{"key":"bla_cbe0.356h","parent_key":null,"label":"Form FDA 356h","mandatory":true,"path_order":2},{"key":"bla_cbe0.description","parent_key":null,"label":"Detailed Description of the Change, Products and Sites Involved","mandatory":true,"path_order":3},{"key":"bla_cbe0.data","parent_key":null,"label":"Data From the Studies Evaluating the Change","mandatory":true,"path_order":4},{"key":"bla_cbe0.validation","parent_key":null,"label":"Validation Protocols, Data and SOP References","mandatory":true,"path_order":5},{"key":"bla_cbe0.labeling","parent_key":null,"label":"Labeling Changes","mandatory":false,"path_order":6},{"key":"CTD","parent_key":null,"label":"Updated CTD Sections","mandatory":false,"path_order":7},{"key":"2.3","parent_key":"CTD","label":"Quality Overall Summary (QOS)","mandatory":false,"path_order":8},{"key":"3.2.S","parent_key":"CTD","label":"Drug Substance","mandatory":false,"path_order":9},{"key":"3.2.P","parent_key":"CTD","label":"Drug Product","mandatory":false,"path_order":10},{"key":"3.2.A","parent_key":"CTD","label":"Appendices (Facilities and Equipment, Adventitious Agents Safety Evaluation, Excipients)","mandatory":false,"path_order":11},{"key":"3.2.R","parent_key":"CTD","label":"Regional Information","mandatory":false,"path_order":12}]$pack$::jsonb
    WHEN 'bla_annual_report:fda:fda-bla-annual-report-v1.0' THEN $pack$[{"key":"bla_annual.cover","parent_key":null,"label":"Cover Letter and Index","mandatory":true,"path_order":1},{"key":"bla_annual.products","parent_key":null,"label":"List of Products Involved","mandatory":true,"path_order":2},{"key":"bla_annual.changes","parent_key":null,"label":"Description of Each Manufacturing and Controls Change","mandatory":true,"path_order":3},{"key":"bla_annual.data","parent_key":null,"label":"Data From Studies and Tests Evaluating Each Change","mandatory":true,"path_order":4},{"key":"bla_annual.labeling","parent_key":null,"label":"Minor Labeling Changes","mandatory":false,"path_order":5}]$pack$::jsonb
    WHEN 'bla_pediatric_report:fda:fda-bla-pediatric-report-v1.0' THEN $pack$[{"key":"bla_ped.summary","parent_key":null,"label":"Summary of Pediatric Labeling and Studies, With Exposure Estimate","mandatory":true,"path_order":1},{"key":"bla_ped.exposure","parent_key":null,"label":"Pediatric Exposure Data","mandatory":false,"path_order":2},{"key":"bla_ped.clinical","parent_key":null,"label":"Analysis of Pediatric Safety and Efficacy Data","mandatory":true,"path_order":3},{"key":"bla_ped.status","parent_key":null,"label":"Status of Pediatric Postmarketing Studies","mandatory":true,"path_order":4}]$pack$::jsonb
    WHEN 'bla_pmr_status_report:fda:fda-bla-pmr-status-report-v1.0' THEN $pack$[{"key":"bla_pmr.cover","parent_key":null,"label":"Cover Letter and Index of Studies","mandatory":true,"path_order":1},{"key":"bla_pmr.status_table","parent_key":null,"label":"Status of Each Postmarketing Requirement and Commitment","mandatory":true,"path_order":2},{"key":"bla_pmr.explanation","parent_key":null,"label":"Explanation of Status and Any Revised Schedule","mandatory":true,"path_order":3}]$pack$::jsonb
    WHEN 'bla_distribution_report:fda:fda-bla-distribution-report-v1.0' THEN $pack$[{"key":"bla_dist.cover","parent_key":null,"label":"Cover Letter","mandatory":true,"path_order":1},{"key":"bla_dist.lots","parent_key":null,"label":"Lot Distribution Data","mandatory":true,"path_order":2}]$pack$::jsonb
    WHEN 'bpdr:fda:fda-bpdr-v1.0' THEN $pack$[{"key":"bpdr.reportability","parent_key":null,"label":"Reportability Assessment","mandatory":true,"path_order":1},{"key":"bpdr.3486","parent_key":null,"label":"Form FDA 3486","mandatory":true,"path_order":2},{"key":"bpdr.description","parent_key":null,"label":"Event Description, Investigation and Corrective Action","mandatory":true,"path_order":3},{"key":"bpdr.lots","parent_key":null,"label":"Affected Lots and Distribution","mandatory":true,"path_order":4}]$pack$::jsonb
    WHEN 'bla_pae_report:fda:fda-bla-pae-report-v1.0' THEN $pack$[{"key":"pae.summary","parent_key":null,"label":"Narrative Summary and Analysis, Including 15-Day Alert Reports","mandatory":true,"path_order":1},{"key":"pae.icsrs","parent_key":null,"label":"Individual Case Safety Reports Not Previously Submitted","mandatory":true,"path_order":2},{"key":"pae.actions","parent_key":null,"label":"History of Actions Taken Since the Last Report","mandatory":true,"path_order":3}]$pack$::jsonb
    WHEN 'cber_master_file:fda:fda-cber-master-file-v1.0' THEN $pack$[{"key":"cber_mf.cover","parent_key":null,"label":"Cover Letter and Administrative Information","mandatory":true,"path_order":1},{"key":"cber_mf.commitment","parent_key":null,"label":"Statement of Commitment","mandatory":true,"path_order":2},{"key":"cber_mf.technical","parent_key":null,"label":"Technical Content","mandatory":true,"path_order":3},{"key":"cber_mf.loa","parent_key":null,"label":"Letters of Authorization","mandatory":true,"path_order":4},{"key":"cber_mf.authorized","parent_key":null,"label":"List of Persons Authorized to Reference","mandatory":true,"path_order":5},{"key":"cber_mf.changes","parent_key":null,"label":"Description of Changes (Amendments)","mandatory":false,"path_order":6}]$pack$::jsonb
    WHEN 'cber_lot_release:fda:fda-cber-lot-release-v1.0' THEN $pack$[{"key":"cber_lr.cover","parent_key":null,"label":"Cover Letter","mandatory":true,"path_order":1},{"key":"cber_lr.protocol","parent_key":null,"label":"Lot Release Protocol","mandatory":true,"path_order":2},{"key":"cber_lr.samples","parent_key":null,"label":"Sample Shipment Record","mandatory":false,"path_order":3}]$pack$::jsonb
    WHEN 'eua_request:fda:fda-eua-request-v1.0' THEN $pack$[{"key":"eua.cover","parent_key":null,"label":"Request Letter","mandatory":true,"path_order":1},{"key":"eua.product","parent_key":null,"label":"Product Description and Intended Use","mandatory":true,"path_order":2},{"key":"eua.criteria","parent_key":null,"label":"Statement on the Statutory Criteria","mandatory":true,"path_order":3},{"key":"eua.fact_sheets","parent_key":null,"label":"Proposed Fact Sheets for Health Care Providers and for Recipients","mandatory":true,"path_order":4},{"key":"eua.conditions","parent_key":null,"label":"Proposed Conditions of Authorization and Safety Monitoring","mandatory":true,"path_order":5},{"key":"eua.data","parent_key":null,"label":"Safety and Effectiveness Data","mandatory":true,"path_order":6},{"key":"eua.cmc","parent_key":null,"label":"Chemistry, Manufacturing and Controls Information","mandatory":true,"path_order":7}]$pack$::jsonb
    END;
    SELECT jsonb_array_length(required_sections), required_sections = tree, superseded_by
      INTO n, same, sup
      FROM c2c_rule_packs
     WHERE doc_type = e->>'doc_type' AND agency = e->>'agency' AND version = e->>'version';
    IF NOT FOUND OR n IS DISTINCT FROM (e->>'nodes')::integer OR same IS NOT TRUE THEN
      RAISE EXCEPTION '%:% % must hold this file''s % nodes; found % (tree matches: %)',
        e->>'doc_type', e->>'agency', e->>'version', e->>'nodes',
        coalesce(n::text, 'no row'), coalesce(same::text, 'n/a');
    END IF;
    IF sup IS NOT NULL AND NOT EXISTS (
      SELECT 1 FROM c2c_rule_packs
       WHERE doc_type = e->>'doc_type' AND agency = e->>'agency' AND version = sup) THEN
      RAISE EXCEPTION '%:% % is superseded by %, which does not exist',
        e->>'doc_type', e->>'agency', e->>'version', sup;
    END IF;
    SELECT count(*) INTO live FROM c2c_rule_packs
     WHERE doc_type = e->>'doc_type' AND agency = e->>'agency' AND superseded_by IS NULL;
    IF live <> 1 THEN
      RAISE EXCEPTION '%:% must have exactly one live pack; found %', e->>'doc_type', e->>'agency', live;
    END IF;
  END LOOP;
END
$mig$;
